import{_ as l,o as t,c as i,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-10-28","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-10-28","date":"2021-10-28T00:00:00.000Z","updated":"2021-11-04T00:00:00.000Z","tags":["Ceph","性能优化","内存分配","分布式存储","Pull Requests"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-10-28.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-10-28.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-10-28.md"};function n(o,e,p,a,_,g){return t(),i("div",null,[...e[0]||(e[0]=[s("<p>在2021年10月28日的Ceph性能会议上，研发人员讨论了一系列性能优化议题，包括内存分配、性能瓶颈和Pull Requests的更新。</p><p><strong>关键细节</strong>：</p><ul><li><p><strong>Pull Requests (PRs)</strong>:</p><ul><li>设置最小分配大小以适应不同设备的最佳I/O大小，并讨论了性能与空间浪费之间的权衡。</li><li>Igor提出改进共享Blob fsck过程，将内存使用从12GB减少到0.5GB，显著改善了内存使用。</li><li>Mark Cogan的工作增加了db store的配置选项，以设置单线程性能调优参数。</li></ul></li><li><p><strong>更新PRs</strong>:</p><ul><li>优化PG peering延迟的PR，Neha将重新定位到master分支。</li><li>MDS移除子树映射从日志的PR，设计文档已提供，仍在进行中。</li><li>优化对象内存分配使用池的旧PR，Gabriel增加了讨论，涉及内存分配的优化。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><p><strong>内存分配优化</strong>:</p><ul><li>讨论了通过预分配区域或重用对象来优化内存分配，减少动态分配的需求。</li><li>提到了使用栈分配、固定大小缓冲区以及slab分配器的可能性。</li><li>讨论了是否应该重新设计协议，以支持更高效的内存使用和减少碎片化。</li></ul></li><li><p><strong>性能瓶颈</strong>:</p><ul><li>提到了messenger组件可能存在的性能瓶颈，建议从这里开始优化。</li><li>讨论了如何通过减少动态分配和优化数据结构来改善性能。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>需要进一步调查和优化内存分配策略，特别是对于高频使用的对象和请求。</li><li>选择一个简单的组件（如messenger）开始优化，以验证假设和方法的有效性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续讨论和优化内存分配策略，特别是对于编码/解码过程。</li><li>开始对messenger组件进行优化，以减少其性能开销。</li><li>收集更多的性能数据和墙钟分析，以帮助确定进一步优化的领域。</li></ul><p>会议强调了通过小步骤开始，逐步改进系统性能的重要性，并鼓励团队成员继续探索和实验这些优化策略。</p>",10)])])}const m=l(r,[["render",n]]);export{c as __pageData,m as default};
